{
  "name": "@spacatty/switchyard",
  "version": "0.3.0",
  "description": "One provider list for your coding agents: a local web UI that shares custom OpenAI-compatible providers between OpenCode, Z-Code, Pi and T3 Code, with automatic model discovery.",
  "keywords": [
    "opencode",
    "zcode",
    "pi",
    "t3code",
    "coding-agent",
    "llm",
    "openai-compatible",
    "providers",
    "models",
    "config",
    "cli"
  ],
  "homepage": "https://github.com/spacatty/switchyard#readme",
  "bugs": {
    "url": "https://github.com/spacatty/switchyard/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/spacatty/switchyard.git"
  },
  "license": "MIT",
  "author": "spacatty",
  "bin": {
    "switchyard": "bin/cli.js",
    "occ-manager": "bin/cli.js"
  },
  "files": [
    "bin",
    "src",
    "public",
    "schema",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "start": "node bin/cli.js",
    "check-schema": "node scripts/check-schema.js",
    "update-schema": "node scripts/check-schema.js --update",
    "test": "node scripts/smoke-test.js",
    "prepublishOnly": "npm run check-schema"
  },
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://opencode.ai/config.json",
  "type": "object",
  "properties": {
    "$schema": {
      "type": "string",
      "description": "JSON schema reference for configuration validation"
    },
    "shell": {
      "type": "string",
      "description": "Default shell to use for terminal and shell tool execution"
    },
    "model": {
      "anyOf": [
        {
          "type": "string",
          "pattern": "^[^/#]+\\/[^#]+(?:#[^#]+)?$"
        },
        {
          "type": "object",
          "properties": {
            "providerID": {
              "type": "string",
              "pattern": "^[^/#]+$"
            },
            "model": {
              "type": "string",
              "pattern": "^[^#]+$"
            },
            "variant": {
              "type": "string",
              "pattern": "^[^#]+$"
            }
          },
          "required": [
            "providerID",
            "model"
          ],
          "additionalProperties": false
        }
      ],
      "description": "Default model to use when no session or agent model is selected"
    },
    "default_agent": {
      "type": "string",
      "description": "Default primary agent to use when no session agent is selected"
    },
    "update": {
      "type": "string",
      "enum": [
        "disable",
        "notify",
        "auto"
      ],
      "description": "Disable updates, notify when one is available, or install updates automatically"
    },
    "share": {
      "type": "string",
      "enum": [
        "manual",
        "auto",
        "disabled"
      ],
      "description": "Control whether sessions may be shared manually, automatically, or not at all"
    },
    "enterprise": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "Enterprise URL"
        }
      },
      "additionalProperties": false,
      "description": "Enterprise sharing service configuration"
    },
    "username": {
      "type": "string",
      "description": "Username displayed in conversations and used for telemetry identity"
    },
    "timezone": {
      "type": "string",
      "description": "IANA time zone for schedules, e.g. America/Los_Angeles. Defaults to the server's local zone"
    },
    "permissions": {
      "$ref": "#/$defs/Permission.Ruleset",
      "description": "Ordered tool permission rules applied to agent tool use"
    },
    "policies": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "enum": [
              "provider.use",
              "tool.use",
              "integration.connect",
              "integration.use",
              "mcp.use",
              "skill.use",
              "plugin.use"
            ]
          },
          "resource": {
            "type": "string"
          },
          "effect": {
            "type": "string",
            "enum": [
              "allow",
              "deny"
            ]
          }
        },
        "required": [
          "action",
          "resource",
          "effect"
        ],
        "additionalProperties": false
      },
      "description": "Ordered policies controlling access to providers, tools, and integrations"
    },
    "agents": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/$defs/Config.AgentEncoded"
      },
      "description": "Named built-in agent overrides and custom agent definitions"
    },
    "snapshots": {
      "type": "boolean",
      "description": "Enable snapshots used for undo and revert behavior"
    },
    "watcher": {
      "type": "object",
      "properties": {
        "ignore": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      },
      "additionalProperties": false,
      "description": "Filesystem watcher configuration"
    },
    "formatter": {
      "anyOf": [
        {
          "type": "boolean"
        },
        {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/$defs/Config.Formatter.EntryEncoded"
          }
        }
      ],
      "description": "Enable built-in formatters or configure formatter overrides"
    },
    "lsp": {
      "anyOf": [
        {
          "type": "boolean"
        },
        {
          "type": "object",
          "additionalProperties": {
            "anyOf": [
              {
                "type": "object",
                "properties": {
                  "disabled": {
                    "type": "boolean",
                    "enum": [
                      true
                    ]
                  }
                },
                "required": [
                  "disabled"
                ],
                "additionalProperties": false
              },
              {
                "$ref": "#/$defs/Config.LSP.ServerEncoded"
              }
            ]
          }
        }
      ],
      "description": "Enable built-in language servers or configure server overrides"
    },
    "media": {
      "type": "object",
      "properties": {
        "image": {
          "type": "object",
          "properties": {
            "auto_resize": {
              "type": "boolean"
            },
            "max_width": {
              "type": "integer",
              "maximum": 9007199254740991,
              "exclusiveMinimum": 0
            },
            "max_height": {
              "type": "integer",
              "maximum": 9007199254740991,
              "exclusiveMinimum": 0
            },
            "max_base64_bytes": {
              "type": "integer",
              "maximum": 9007199254740991,
              "exclusiveMinimum": 0
            }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false,
      "description": "Media processing configuration"
    },
    "tool_output": {
      "type": "object",
      "properties": {
        "max_lines": {
          "type": "integer",
          "maximum": 9007199254740991,
          "exclusiveMinimum": 0,
          "description": "Maximum lines of tool output before it is truncated and saved to disk (default: 2000)"
        },
        "max_bytes": {
          "type": "integer",
          "maximum": 9007199254740991,
          "exclusiveMinimum": 0,
          "description": "Maximum bytes of tool output before it is truncated and saved to disk (default: 51200)"
        }
      },
      "additionalProperties": false,
      "description": "Tool output truncation thresholds"
    },
    "mcp": {
      "type": "object",
      "properties": {
        "timeout": {
          "type": "object",
          "properties": {
            "startup": {
              "type": "integer",
              "maximum": 9007199254740991,
              "exclusiveMinimum": 0
            },
            "catalog": {
              "type": "integer",
              "maximum": 9007199254740991,
              "exclusiveMinimum": 0
            },
            "execution": {
              "type": "integer",
              "maximum": 9007199254740991,
              "exclusiveMinimum": 0
            }
          },
          "additionalProperties": false
        },
        "servers": {
          "type": "object",
          "additionalProperties": {
            "anyOf": [
              {
                "$ref": "#/$defs/Mcp.LocalConfigEncoded"
              },
              {
                "$ref": "#/$defs/Mcp.RemoteConfigEncoded"
              }
            ]
          }
        }
      },
      "additionalProperties": {
        "anyOf": [
          {
            "anyOf": [
              {
                "$ref": "#/$defs/McpLocalConfig"
              },
              {
                "$ref": "#/$defs/McpRemoteConfig"
              }
            ]
          },
          {
            "type": "object",
            "properties": {
              "enabled": {
                "type": "boolean"
              }
            },
            "required": [
              "enabled"
            ],
            "additionalProperties": false
          }
        ],
        "deprecated": true
      },
      "description": "MCP server configuration"
    },
    "compaction": {
      "type": "object",
      "properties": {
        "auto": {
          "type": "boolean",
          "description": "Enable automatic compaction when context is full (default: true)"
        },
        "keep": {
          "type": "object",
          "properties": {
            "tokens": {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            }
          },
          "additionalProperties": false
        },
        "buffer": {
          "anyOf": [
            {
              "$ref": "#/$defs/Config.Compaction.Percent"
            },
            {
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            }
          ]
        },
        "prune": {
          "type": "boolean",
          "description": "Enable pruning of old tool outputs (default: false)",
          "deprecated": true
        },
        "tail_turns": {
          "minimum": 0,
          "type": "integer",
          "maximum": 9007199254740991,
          "description": "Maximum number of recent user turns, including their following assistant/tool responses, to keep verbatim during compaction. By default retention is limited only by the preserved token budget.",
          "deprecated": true
        },
        "preserve_recent_tokens": {
          "minimum": 0,
          "type": "integer",
          "maximum": 9007199254740991,
          "description": "Maximum number of tokens from recent turns to preserve verbatim after compaction",
          "deprecated": true
        },
        "reserved": {
          "minimum": 0,
          "type": "integer",
          "maximum": 9007199254740991,
          "description": "Token buffer for compaction. Leaves enough window to avoid overflow during compaction.",
          "deprecated": true
        }
      },
      "additionalProperties": false,
      "description": "Conversation compaction behavior"
    },
    "skills": {
      "description": "Additional paths or URLs to discover skills from",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Additional paths or URLs to discover skills from"
        },
        {
          "type": "object",
          "properties": {
            "paths": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Additional paths to skill folders"
            },
            "urls": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "URLs to fetch skills from (e.g., https://example.com/.well-known/skills/)"
            }
          },
          "additionalProperties": false,
          "description": "Additional skill folder paths",
          "deprecated": true
        }
      ]
    },
    "commands": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/$defs/Config.CommandEncoded"
      },
      "description": "Named slash command definitions"
    },
    "instructions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Additional paths or URLs supplying ambient instructions"
    },
    "references": {
      "type": "object",
      "additionalProperties": {
        "anyOf": [
          {
            "type": "string"
          },
          {
            "$ref": "#/$defs/Config.Reference.GitEncoded"
          },
          {
            "$ref": "#/$defs/Config.Reference.LocalEncoded"
          }
        ]
      },
      "description": "Named local directories or Git repositories available as external context",
      "properties": {}
    },
    "websearch": {
      "anyOf": [
        {
          "type": "boolean",
          "enum": [
            false
          ]
        },
        {
          "$ref": "#/$defs/ConfigWebSearch.InfoEncoded"
        }
      ],
      "description": "Web search provider selection"
    },
    "plugins": {
      "type": "array",
      "items": {
        "anyOf": [
          {
            "type": "string"
          },
          {
            "$ref": "#/$defs/Config.Plugin.EntryEncoded"
          }
        ]
      },
      "description": "Ordered plugin enablement directives and external package declarations"
    },
    "worktree": {
      "$ref": "#/$defs/Config.Worktree",
      "description": "Directory defaults for local worktree creation"
    },
    "warming": {
      "anyOf": [
        {
          "type": "boolean"
        },
        {
          "$ref": "#/$defs/Config.WarmingEncoded"
        }
      ],
      "description": "Keep recently active sessions warm with transient model requests (default: false)"
    },
    "providers": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/$defs/Config.ProviderEncoded"
      }
    },
    "experimental": {
      "type": "object",
      "properties": {
        "portable_shell_scanner": {
          "type": "boolean"
        },
        "todo": {
          "type": "boolean"
        },
        "background_compaction": {
          "type": "boolean"
        },
        "media_blob": {
          "type": "boolean"
        },
        "image_generate": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "object",
              "properties": {
                "model": {
                  "anyOf": [
                    {
                      "type": "string",
                      "pattern": "^[^/#]+\\/[^#]+(?:#[^#]+)?$"
                    },
                    {
                      "type": "object",
                      "properties": {
                        "providerID": {
                          "type": "string",
                          "pattern": "^[^/#]+$"
                        },
                        "model": {
                          "type": "string",
                          "pattern": "^[^#]+$"
                        },
                        "variant": {
                          "type": "string",
                          "pattern": "^[^#]+$"
                        }
                      },
                      "required": [
                        "providerID",
                        "model"
                      ],
                      "additionalProperties": false
                    }
                  ]
                }
              },
              "additionalProperties": false
            }
          ]
        },
        "schedules": {
          "type": "boolean"
        },
        "artifacts": {
          "type": "boolean"
        },
        "subagent_depth": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "location_idle_timeout": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "boolean",
              "enum": [
                false
              ]
            }
          ]
        },
        "policies": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "action": {
                "type": "string",
                "enum": [
                  "provider.use",
                  "tool.use",
                  "integration.connect",
                  "integration.use",
                  "mcp.use",
                  "skill.use",
                  "plugin.use"
                ]
              },
              "resource": {
                "type": "string"
              },
              "effect": {
                "type": "string",
                "enum": [
                  "allow",
                  "deny"
                ]
              }
            },
            "required": [
              "action",
              "resource",
              "effect"
            ],
            "additionalProperties": false
          },
          "d
…[文件过长——仅保留首 16KB 与末 8KB]…
     "$ref": "#/$defs/Model.MediaInput"
        }
      },
      "additionalProperties": false
    },
    "Config.Model.Settings": {
      "type": "object",
      "properties": {
        "compaction": {
          "$ref": "#/$defs/Provider.Compaction"
        },
        "cache": {
          "$ref": "#/$defs/Provider.Cache"
        },
        "encoding": {
          "$ref": "#/$defs/Provider.Encoding"
        }
      },
      "allOf": [
        {
          "type": "object",
          "additionalProperties": {
            "anyOf": [
              {},
              {
                "type": "null"
              }
            ]
          }
        }
      ]
    },
    "Config.Model.Reasoning": {
      "anyOf": [
        {
          "type": "object",
          "properties": {
            "supported": {
              "type": "boolean",
              "enum": [
                false
              ]
            }
          },
          "required": [
            "supported"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "properties": {
            "supported": {
              "type": "boolean",
              "enum": [
                true
              ]
            },
            "toggle": {
              "type": "boolean"
            },
            "effort": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "budget": {
              "type": "object",
              "properties": {
                "min": {
                  "type": "integer",
                  "minimum": -9007199254740991,
                  "maximum": 9007199254740991
                },
                "max": {
                  "type": "integer",
                  "minimum": -9007199254740991,
                  "maximum": 9007199254740991
                }
              },
              "additionalProperties": false
            }
          },
          "required": [
            "supported"
          ],
          "additionalProperties": false
        }
      ]
    },
    "Config.Model.Capabilities": {
      "type": "object",
      "properties": {
        "tools": {
          "type": "boolean"
        },
        "input": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "output": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "temperature": {
          "type": "boolean"
        },
        "reasoning": {
          "$ref": "#/$defs/Config.Model.Reasoning"
        }
      },
      "additionalProperties": false
    },
    "Config.Model.VariantSettings": {
      "type": "object",
      "properties": {
        "compaction": {
          "$ref": "#/$defs/Provider.Compaction"
        },
        "encoding": {
          "$ref": "#/$defs/Provider.Encoding"
        }
      },
      "allOf": [
        {
          "type": "object",
          "additionalProperties": {
            "anyOf": [
              {},
              {
                "type": "null"
              }
            ]
          }
        }
      ]
    },
    "Money.USDPerMillionTokens": {
      "type": "number"
    },
    "Config.Model.CostEncoded": {
      "type": "object",
      "properties": {
        "tier": {
          "type": "object",
          "properties": {
            "type": {
              "type": "string",
              "enum": [
                "context"
              ]
            },
            "size": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            }
          },
          "required": [
            "type",
            "size"
          ],
          "additionalProperties": false
        },
        "input": {
          "$ref": "#/$defs/Money.USDPerMillionTokens"
        },
        "output": {
          "$ref": "#/$defs/Money.USDPerMillionTokens"
        },
        "cache": {
          "type": "object",
          "properties": {
            "read": {
              "$ref": "#/$defs/Money.USDPerMillionTokens"
            },
            "write": {
              "$ref": "#/$defs/Money.USDPerMillionTokens"
            }
          },
          "additionalProperties": false
        }
      },
      "required": [
        "input",
        "output"
      ],
      "additionalProperties": false
    },
    "Config.ModelEncoded": {
      "type": "object",
      "properties": {
        "modelID": {
          "type": "string"
        },
        "type": {
          "$ref": "#/$defs/Model.Type"
        },
        "family": {
          "type": "string"
        },
        "name": {
          "type": "string"
        },
        "releaseDate": {
          "type": "string",
          "pattern": "^\\d{4}-\\d{2}(-\\d{2})?$",
          "description": "Release date as YYYY-MM-DD or YYYY-MM"
        },
        "compatibility": {
          "$ref": "#/$defs/Model.Compatibility"
        },
        "package": {
          "type": "string"
        },
        "settings": {
          "$ref": "#/$defs/Config.Model.Settings"
        },
        "headers": {
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        },
        "body": {
          "type": "object"
        },
        "capabilities": {
          "$ref": "#/$defs/Config.Model.Capabilities"
        },
        "variants": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "id": {
                "type": "string"
              },
              "settings": {
                "$ref": "#/$defs/Config.Model.VariantSettings"
              },
              "headers": {
                "type": "object",
                "additionalProperties": {
                  "type": "string"
                }
              },
              "body": {
                "type": "object"
              }
            },
            "required": [
              "id"
            ],
            "additionalProperties": false
          }
        },
        "cost": {
          "anyOf": [
            {
              "$ref": "#/$defs/Config.Model.CostEncoded"
            },
            {
              "type": "array",
              "items": {
                "$ref": "#/$defs/Config.Model.CostEncoded"
              }
            }
          ]
        },
        "disabled": {
          "type": "boolean"
        },
        "limit": {
          "type": "object",
          "properties": {
            "context": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "input": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "output": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },
    "Config.ProviderEncoded": {
      "type": "object",
      "properties": {
        "canonical": {
          "$ref": "#/$defs/Provider.ID"
        },
        "name": {
          "type": "string"
        },
        "env": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "package": {
          "type": "string"
        },
        "compatibility": {
          "$ref": "#/$defs/Provider.Compatibility"
        },
        "settings": {
          "$ref": "#/$defs/Config.Provider.Settings"
        },
        "headers": {
          "type": "object",
          "additionalProperties": {
            "type": "string"
          }
        },
        "body": {
          "type": "object"
        },
        "models": {
          "type": "object",
          "additionalProperties": {
            "$ref": "#/$defs/Config.ModelEncoded"
          }
        }
      },
      "additionalProperties": false
    }
  },
  "allowComments": true,
  "allowTrailingCommas": true
}
